sys_security_acl.script:
answer = false;

var access =
    new CampusMatchAccess();

if (access.isStaff()) {

    answer = true;

}
else {

    var lostId =
        current.getValue(
            'lost_item'
        );

    var foundId =
        current.getValue(
            'found_item'
        );


    if (
        lostId &&
        foundId
    ) {

        var lost =
            new GlideRecord(
                'x_snc_campusmatch_campusmatch_item'
            );

        var found =
            new GlideRecord(
                'x_snc_campusmatch_campusmatch_item'
            );


        if (
            lost.get(lostId) &&
            found.get(foundId)
        ) {

            answer =
                access.canViewMatch(
                    lost,
                    found
                );

        }

    }

}
